// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 bn, address actor) public {
        ts = bound(ts, 1, type(uint256).max / 2);
        bn = bound(bn, 1, type(uint256).max / 2);
        vm.assume(actor != address(0));

        vm.roll(bn);
        vm.warp(ts);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // General rule: the contract remembers the timestamp of the last call.
        assertEq(c.pastBlockTime(), block.timestamp);
    }
}
